const PASHTO_SCRIPT = "(() => {\n 'use strict';\n const menu = document.getElementById('ps-menu');\n const nav = document.getElementById('ps-nav');\n if(menu&&nav){menu.addEventListener('click',()=>{const expanded=menu.getAttribute('aria-expanded')==='true';menu.setAttribute('aria-expanded',String(!expanded));nav.classList.toggle('open',!expanded);});nav.addEventListener('click',e=>{if(e.target.closest('a')){nav.classList.remove('open');menu.setAttribute('aria-expanded','false');}});}\n const form=document.getElementById('ps-enquiry');\n if(!form)return;\n const error=document.getElementById('ps-form-error');\n form.addEventListener('submit',e=>{\n  e.preventDefault();\n  const fd=new FormData(form),name=String(fd.get('name')||'').trim(),program=String(fd.get('program')||'').trim();\n  if(name.length<2||!program){error.textContent='مهرباني وکړئ نوم او پروګرام وټاکئ.';return;}\n  error.textContent='';\n  const m=['سلام! زه د The TOEFL House د پروګرامونو په اړه معلومات غواړم.','نوم: '+name,'پروګرام: '+program,'وخت: '+String(fd.get('shift')||'هر مناسب وخت'),'ټولګی: '+String(fd.get('mode')||'حضوري'),'شمېره: '+String(fd.get('phone')||'نه ده ورکړل شوې'),'د TOEFL هدف: '+String(fd.get('goal')||'نه دی ټاکل شوی'),'مهرباني وکړئ د سویې معلومولو او نوم‌لیکنې په اړه معلومات راکړئ.'].join('\\n');\n  const link='https://wa.me/93794357509?text='+encodeURIComponent(m);\n  const preview=document.getElementById('ps-whatsapp-preview');\n  if(preview){preview.href=link;preview.hidden=false;preview.focus();}\n });\n})();\n\n// Feature parity for Pashto route. All data-dependent choices use the live DOM\n// rendered from the published CMS, not a duplicate client-side catalog.\n(() => {\n 'use strict';\n const $=id=>document.getElementById(id);\n for(const [dataAttr,itemAttr] of [['programFilter','programGroup'],['curriculumFilter','curriculumGroup']]){\n   const buttons=[...document.querySelectorAll(`[data-${dataAttr.replace(/[A-Z]/g,m=>'-'+m.toLowerCase())}]`)];\n   const cards=[...document.querySelectorAll(`[data-${itemAttr.replace(/[A-Z]/g,m=>'-'+m.toLowerCase())}]`)];\n   buttons.forEach(button=>button.addEventListener('click',()=>{\n     const value=button.dataset[dataAttr];\n     buttons.forEach(b=>b.setAttribute('aria-pressed',String(b===button)));\n     cards.forEach(c=>{c.hidden=value!=='all' && c.dataset[itemAttr]!==value;});\n   }));\n }\n const search=$('ps-faq-search'),faq=$('ps-faq-list');\n if(search&&faq){const items=[...faq.querySelectorAll('details')];search.addEventListener('input',()=>{\n   const q=search.value.trim().toLocaleLowerCase('ps-AF');let visible=0;\n   for(const item of items){const show=item.textContent.toLocaleLowerCase('ps-AF').includes(q);item.hidden=!show;if(show)visible++;}\n   $('ps-faq-empty').hidden=visible!==0;\n });}\n const scoreSelects=[...document.querySelectorAll('[data-toefl-score]')];\n if(scoreSelects.length===4){const render=()=>{\n   const nums=scoreSelects.map(s=>Number(s.value));\n   const v=Math.round((nums.reduce((a,b)=>a+b,0)/4)*2)/2;\n   $('ps-score-total').innerHTML=v.toFixed(1)+' <small>/ 6</small>';\n   const btn=$('ps-score-enquire');\n   if(btn)btn.dataset.targetScore=String(v);\n };scoreSelects.forEach(s=>s.addEventListener('change',render));render();}\n const advisor=$('ps-advisor');\n if(advisor){let step=0;const steps=[...advisor.querySelectorAll('[data-advisor-step]')];const next=$('ps-advisor-next'),restart=$('ps-advisor-restart'),result=$('ps-advisor-result');\n const reset=()=>{step=0;advisor.querySelectorAll('input[type=radio]').forEach(x=>x.checked=false);result.hidden=true;next.hidden=false;restart.hidden=true;render();};\n const render=()=>{steps.forEach((el,i)=>el.hidden=i!==step);$('ps-advisor-progress').textContent=`پوښتنه ${step+1} له ۳`;next.textContent=step===2?'وړاندیز وګورئ':'بل ګام';};\n next.addEventListener('click',()=>{\n   const field=steps[step];const selected=field.querySelector('input[type=radio]:checked');\n   if(!selected){field.classList.add('needs-choice');field.querySelector('input')?.focus();return;}field.classList.remove('needs-choice');\n   if(step<2){step++;render();return;}\n   const skill=advisor.querySelector('[name=advisor-skill]:checked').value;\n   const goal=advisor.querySelector('[name=advisor-goal]:checked').value;\n   const mode=advisor.querySelector('[name=advisor-mode]:checked').value;\n   const id=goal==='toefl'?'toefl-preparation':goal==='academic'?'academic-english':goal==='teaching'?'teacher-training':skill==='beginner'?'general-english':'special-speaking';\n   const course=document.getElementById('program-'+id)?.querySelector('h3')?.textContent||'عمومي انګلیسي';\n   result.replaceChildren();const h=document.createElement('h3');h.textContent='زموږ لومړنی وړاندیز: '+course;result.append(h);\n   const p=document.createElement('p');p.textContent=mode==='online'?'د Zoom انفرادي صنفونه د استاد د شتون له مخې تنظیمېږي. د کره سویې لپاره وړیا ارزونه وکړئ.':'د وړیا سویې معلومولو له لارې خپله کره کچه او موجود صنف تایید کړئ.';result.append(p);\n   const link=document.createElement('a');link.href='#admissions';link.className='btn';link.textContent='له پذیرش سره اړیکه ونیسئ';\n   link.addEventListener('click',()=>{const sel=document.querySelector('#ps-enquiry select[name=program]');const option=[...sel.options].find(o=>o.dataset.programId===id);if(option)sel.value=option.value;\n     const modeSelect=document.querySelector('#ps-enquiry select[name=mode]');if(modeSelect&&mode==='online')modeSelect.selectedIndex=1;});\n   result.append(link);result.hidden=false;steps.forEach(s=>s.hidden=true);next.hidden=true;restart.hidden=false;$('ps-advisor-progress').textContent='لومړنی وړاندیز';\n });restart.addEventListener('click',reset);render();\n }\n const scoreLink=$('ps-score-enquire');\n if(scoreLink)scoreLink.addEventListener('click',()=>{const value=scoreLink.dataset.targetScore||'4.0';const sel=document.querySelector('#ps-enquiry select[name=program]');const option=[...sel.options].find(o=>o.dataset.programId==='toefl-preparation');if(option)sel.value=option.value;\n   let note=$('ps-score-note');if(!note){note=document.createElement('input');note.type='hidden';note.name='goal';note.id='ps-score-note';sel.closest('form').append(note);}note.value='د TOEFL iBT هدف: '+value+' له ۶ څخه';\n });\n const form=$('ps-enquiry');if(form){form.addEventListener('submit',()=>{},true);}\n})();\n";
const PASHTO_ADMIN_SCRIPT = "(() => {\n 'use strict';\n const form=document.getElementById('ps-editor-form'),fields=document.getElementById('ps-editor-fields'),status=document.getElementById('ps-editor-status'),version=document.getElementById('ps-version'),history=document.getElementById('ps-editor-history'),rows=document.getElementById('ps-history-rows');\n const label={hero:'سرلیک او پېژندنه',navigation:'د پاڼې لېست',announcement:'د اعلانونو کرښه',statistics:'شمېرې او پایلې',journey:'د زده‌کړې پړاوونه',programsIntro:'د پروګرامونو سرلیکونه',programs:'زده‌کړیز پروګرامونه',schedule:'د مهالوېش متنونه',announcements:'خبرتیاوې',about:'زموږ په اړه',admissions:'د نوم‌لیکنې فورم',faq:'ډېرې پوښتل کېدونکې پوښتنې',contact:'اړیکې',editor:'د پنل متنونه',eyebrow:'لنډه پېژندنه',title:'سرلیک',description:'تفصیل',lead:'لنډ متن',subtitle:'فرعي سرلیک',summary:'لنډ معلومات',duration:'موده',highlights:'ځانګړتیاوې',recommended:'د چا لپاره',q:'پوښتنه',a:'ځواب',text:'متن',date:'نېټه',cta:'د لومړۍ تڼۍ متن',explore:'د پروګرامونو تڼۍ',address:'پته',hours:'کاري ساعتونه',name:'نوم',nameHint:'د نوم بېلګه',items:'توکي',stages:'پړاوونه',steps:'ګامونه',value:'شمېره',label:'تشریحي نوم',id:'شناسه (ساتل کېږي)',image:'انځور'};\n let doc=null,revision=0,owner=false,busy=false;\n const get=async(path,opts={})=>{const r=await fetch(path,{credentials:'same-origin',cache:'no-store',headers:{Accept:'application/json',...(opts.body?{'Content-Type':'application/json'}:{})},...opts});const x=await r.json().catch(()=>({}));if(!r.ok)throw new Error(x.error||`HTTP ${r.status}`);return x};\n const el=(tag,cls='',text='')=>{const n=document.createElement(tag);if(cls)n.className=cls;if(text)n.textContent=text;return n};\n function canEdit(path){return !path.endsWith('.id') && !/\\.statistics\\[\\d+\\]\\.value$/.test(path)}\n function addField(parent,val,path,name){\n  if(typeof val==='string'){\n   if(!canEdit(path))return;\n   const container=el('label','field'),title=el('span','',label[name]||name),long=val.length>105||['description','summary','text','about','mission','lead','a'].includes(name);\n   const input=el(long?'textarea':'input');if(long){input.rows=val.length>300?5:3}else input.type='text';input.value=val;input.maxLength=1700;\n   input.addEventListener('input',()=>{const pieces=path.replace(/\\[(\\d+)\\]/g,'.$1').split('.').filter(Boolean);let ref=doc;for(let i=0;i<pieces.length-1;i++)ref=ref[pieces[i]];ref[pieces.at(-1)]=input.value;});\n   container.append(title,input);parent.append(container);return;\n  }\n  if(Array.isArray(val)){\n   val.forEach((v,i)=>{const box=el('details'),sum=el('summary','',`${label[name]||name} ${i+1}`);box.append(sum);addField(box,v,path+`[${i}]`,name);parent.append(box)});return;\n  }\n  if(val&&typeof val==='object')for(const [key,value]of Object.entries(val)){\n   if(value&&typeof value==='object'){const sub=el('details'),sum=el('summary','',label[key]||key);sub.append(sum);addField(sub,value,path+'.'+key,key);parent.append(sub)}else addField(parent,value,path+'.'+key,key);\n  };\n }\n const render=()=>{fields.replaceChildren();const names=Object.keys(doc).filter(x=>x!=='editor');names.forEach((key,i)=>{const section=el('details');if(i===0)section.open=true;const title=el('summary','',label[key]||key);section.append(title);addField(section,doc[key],key,key);fields.append(section)});version.textContent='د پښتو خپرې شوې نسخې شمېره: '+revision;form.hidden=false;};\n const load=async()=>{try{const response=await get('/api/admin/pashto');doc=response.content;revision=response.revision;owner=!!response.owner;render();status.textContent='محتوا خوندي ده. بدلونونه یوازې د «خپاره کړئ» له تڼۍ وروسته خپرېږي.';if(owner)loadHistory();}catch(e){status.textContent='ننوتل اړین دي. لومړی اصلي پنل /admin/ ته ننوځئ، بیا دا پاڼه بیا پرانیزئ. ('+e.message+')';}};\n form.addEventListener('submit',async e=>{e.preventDefault();if(busy||!doc)return;if(!confirm('ایا غواړئ د پښتو نوې نسخه د ټولو لیدونکو لپاره خپره کړئ؟'))return;busy=true;status.textContent='خپرېږي…';try{const x=await get('/api/admin/pashto',{method:'POST',body:JSON.stringify({content:doc,baseRevision:revision})});revision=x.revision;status.textContent='✓ د پښتو نوې نسخه خپره شوه. د نسخې شمېره: '+revision;version.textContent='د پښتو خپرې شوې نسخې شمېره: '+revision;if(owner)loadHistory();}catch(err){status.textContent='بدلونونه خپاره نه شول: '+err.message;}finally{busy=false;}});\n const loadHistory=async()=>{try{const r=await get('/api/admin/pashto-history');history.hidden=false;rows.replaceChildren();for(const item of r.revisions){const line=el('div','historyline'),caption=el('span','',`نسخه ${item.revision} — ${item.updated_at} — ${item.action}`),btn=el('button','btn alt','بېرته راوستل');btn.type='button';btn.addEventListener('click',()=>restore(item.revision));line.append(caption,btn);rows.append(line);}}catch(e){history.hidden=true;}};\n const restore=async rev=>{const text=prompt('د نسخه '+rev+' د بېرته راوستلو لپاره RESTORE ولیکئ:');if(text!=='RESTORE')return;try{const r=await get('/api/admin/pashto-restore',{method:'POST',body:JSON.stringify({revision:rev,baseRevision:revision,confirmation:'RESTORE'})});doc=r.content;revision=r.revision;render();status.textContent='✓ نسخه بېرته راوګرځول شوه؛ نوې نسخه '+revision+' ثبت شوه.';loadHistory();}catch(e){status.textContent='بېرته راوستل بریالي نه شول: '+e.message;}};\n load();\n})();\n";
