 if(locale==='en'){
  statement='TOEFL Preparation lasts 4 months.';
  current=current
   .replace(/(?:The\s+)?TOEFL Preparation lasts\s*(?:2|two|4|four)\s*months?\.?/gi,statement)
   .replace(/Confirm the TOEFL Preparation duration and other course schedules with admissions\.?/gi,'TOEFL Preparation lasts 4 months. Confirm other course schedules with admissions.');
 }else if(locale==='fa'){
  statement='دورهٔ آمادگی تافل ۴ ماهه است.';
  current=current
   .replace(/دورهٔ آمادگی تافل\s*[۲2۴4]\s*ماهه است\.?/g,statement)
   .replace(/مدت دقیق دورهٔ تافل و تقسیم اوقات سایر دوره‌ها را با پذیرش تأیید کنید\.?/g,'دورهٔ آمادگی تافل ۴ ماهه است. تقسیم اوقات سایر دوره‌ها را با پذیرش تأیید کنید.');
 }else{
  statement='د TOEFL چمتووالي دوره څلور میاشتې ده.';
  current=current
   .replace(/د TOEFL چمتووالی دوه میاشتې دی\.?/g,statement)
   .replace(/د TOEFL چمتووالي دوره دوه میاشتې ده\.?/g,statement)
   .replace(/د TOEFL کورس کره موده او اوسني وختونه له ادارې سره تایید کړئ\.?/g,'د TOEFL چمتووالي دوره څلور میاشتې ده. اوسني وختونه له ادارې سره تایید کړئ.');
 }
 if(!current.includes(statement))current=(current.trim()+' '+statement).trim();
