 try{
  const row=await env.CMS_DB.prepare('SELECT body,revision,updated_at FROM pashto_content WHERE id=?').bind(psSlug).first();
  if(row){const content=psValidate(JSON.parse(row.body));return {content,revision:row.revision,updatedAt:row.updated_at};}
 }catch(e){if(!/no such table:\s*pashto_content/i.test(String(e)))throw e;}
