function psValidate(input){
 const visit=(obj,model,path='',depth=0)=>{
  if(depth>14)throw Error('Invalid data structure');
  if(typeof model==='string'){
    if(typeof obj!=='string'||obj.length>1700||/[\u0000-\u0008\u000b-\u001f]/.test(obj))throw Error('Invalid Pashto text: '+path);
    if(path.endsWith('.id') && obj!==model)throw Error('Protected identifier: '+path);
    if(/\.statistics\[\d+\]\.value$/.test(path)&&obj!==model)throw Error('Protected statistic');
    return obj.trim();
  }
  if(Array.isArray(model)){
    if(!Array.isArray(obj)||obj.length!==model.length)throw Error('Unexpected list structure: '+path);
    return model.map((m,i)=>visit(obj[i],m,path+'['+i+']',depth+1));
  }
  if(!model||typeof model!=='object'||!obj||typeof obj!=='object'||Array.isArray(obj))throw Error('Invalid content object: '+path);
  const result={};for(const key of Object.keys(model))result[key]=visit(obj[key],model[key],path+'.'+key,depth+1);
  return result;
 };
 const validated=visit(input,PASHTO_DEFAULT);
 const approvedToefl=PASHTO_DEFAULT.programs.find(p=>p.id==='toefl-preparation');
 const toeflIndex=validated.programs.findIndex(p=>p.id==='toefl-preparation');
 if(!approvedToefl||toeflIndex<0)throw Error('Missing official Pashto TOEFL program');
 validated.programs[toeflIndex]=officialToeflProgram(validated.programs[toeflIndex],approvedToefl,'ps');
 validated.faq.items[4].a=officialDurationFaq(validated.faq.items[4].a,'ps');
 for(const p of validated.programs)if(!p.title||!p.summary||!p.duration)throw Error('Program details are required');
 if(!validated.hero.title||!validated.hero.description)throw Error('Hero text is required');
 return validated;
}
