   const pashtoPage=html.replace(/<html[^>]*>/i,'<html lang="ps-AF" dir="rtl">')
     .replace(/<title>[^<]*<\/title>/i,'<title>له لومړي ګام څخه تر TOEFL پورې | The TOEFL House</title>')
     .replace(/<link rel="canonical"[^>]*>/i,`<link rel="canonical" href="${origin}/ps/">`)
     .replace(/<meta property="og:locale"[^>]*>/i,'<meta property="og:locale" content="ps_AF">')
     .replace(/<meta property="og:title"[^>]*>/i,'<meta property="og:title" content="The TOEFL House | پښتو">')
     .replace(/<meta name="description"[^>]*>/i,'<meta name="description" content="The TOEFL House په کابل کې د انګلیسي ژبې زده‌کړه، TOEFL چمتووالی او وړیا سویې معلومول.">')
     .replace(/<meta property="og:description"[^>]*>/i,'<meta property="og:description" content="په کابل کې عمومي او اکاډمیکه انګلیسي، TOEFL چمتووالی او وړیا سویې معلومول.">')
     .replace(/<meta name="twitter:title"[^>]*>/i,'<meta name="twitter:title" content="The TOEFL House | پښتو">')
     .replace(/<meta name="twitter:description"[^>]*>/i,'<meta name="twitter:description" content="د انګلیسي ژبې زده‌کړه او TOEFL چمتووالی په کابل کې.">')
